begin;
create table if not exists public.profiles (
 id text primary key,
 nickname text not null check (length(trim(nickname)) between 1 and 40),
 bio text not null default '',
 interests text[] not null default '{}',
 taste jsonb not null default '{"activity":50,"space":50,"environment":50,"content":50,"pace":50}',
 is_demo boolean not null default true,
 created_at timestamptz not null default now()
);
create table if not exists public.courses (
 id text primary key,
 title text not null check (length(trim(title)) between 1 and 100),
 author_id text not null references public.profiles(id),
 region text not null,
 place_ids text[] not null check (cardinality(place_ids) between 2 and 7),
 tags text[] not null default '{}',
 cover_place_id text not null references public.places(id),
 transport text not null check (transport in ('도보','대중교통','자동차')),
 schedule jsonb not null check (jsonb_typeof(schedule) = 'array'),
 description text not null default '',
 hours numeric not null check (hours > 0 and hours <= 24),
 is_demo boolean not null default true,
 created_at timestamptz not null default now(),
 check (cover_place_id = any(place_ids))
);
create index if not exists courses_author_id_idx on public.courses(author_id);
create index if not exists courses_region_idx on public.courses(region);

-- Read/write through the backend service key only until authentication exists.
alter table public.profiles enable row level security;
alter table public.courses enable row level security;
revoke all on public.profiles, public.courses from anon, authenticated;
grant select, insert, update, delete on public.profiles, public.courses to service_role;

create or replace function public.validate_course_schedule()
returns trigger language plpgsql set search_path = public as $$
declare item jsonb; idx integer := 0;
begin
 if cardinality(new.place_ids) <> (select count(distinct id) from unnest(new.place_ids) as ids(id)) then
  raise exception 'Duplicate place IDs are not allowed';
 end if;
 if exists (select 1 from unnest(new.place_ids) as ids(id) where id is null or not exists (select 1 from public.places p where p.id = ids.id)) then
  raise exception 'Unknown place ID';
 end if;
 if jsonb_array_length(new.schedule) <> cardinality(new.place_ids) then
  raise exception 'Schedule length must match place IDs';
 end if;
 for item in select value from jsonb_array_elements(new.schedule) loop
  idx := idx + 1;
  if item->>'place_id' is distinct from new.place_ids[idx]
     or coalesce(item->>'label','') = ''
     or coalesce(item->>'start_time','') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
     or coalesce(item->>'duration_minutes','') !~ '^[0-9]+$' then
   raise exception 'Invalid schedule item or order';
  end if;
  if (item->>'duration_minutes')::integer not between 1 and 1440 then
   raise exception 'Invalid visit duration';
  end if;
 end loop;
 return new;
end;
$$;
create or replace trigger validate_course_schedule_trigger
before insert or update on public.courses
for each row execute function public.validate_course_schedule();








on conflict (id) do nothing;

on conflict (id) do nothing;

commit;
