insert into public.profiles (id,nickname,bio,interests,taste,is_demo) values
('demo-jaehun','재훈','직접 참여하는 인터랙션·체험과 야외 자연 활동을 알찬 일정으로 즐겨요.',ARRAY['인터랙션','체험','액티비티','야외','자연']::text[],'{"activity": 90, "space": 90, "environment": 90, "content": 90, "pace": 90}'::jsonb,true),
('demo-jieun','지은','보드게임·방탈출과 과일모찌·디저트를 좋아하고 자연 속 캠핑과 체험을 여유롭게 즐겨요.',ARRAY['보드게임','방탈출','과일모찌','디저트','캠핑','체험','야외','자연']::text[],'{"activity": 80, "space": 85, "environment": 85, "content": 85, "pace": 20}'::jsonb,true),
('demo-yujeong','유정','사진과 힐링, 미식을 즐기며 도시의 실내 공간에서 여유롭게 쉬어요.',ARRAY['포토','힐링','미식','휴식','실내','도시']::text[],'{"activity": 20, "space": 20, "environment": 20, "content": 50, "pace": 20}'::jsonb,true),
('demo-sumin','수민','도시의 빵집과 실내 관람 공간에서 여유롭게 쉬는 여행을 좋아해요.',ARRAY['빵','휴식','실내','도시','관람']::text[],'{"activity": 20, "space": 20, "environment": 20, "content": 20, "pace": 20}'::jsonb,true),
('demo-hwibin','휘빈','자연 속 캠핑과 산책, 힐링과 맛있는 한 끼를 여유롭게 즐겨요.',ARRAY['캠핑','자연','산책','힐링','야외','맛집']::text[],'{"activity": 40, "space": 90, "environment": 90, "content": 50, "pace": 20}'::jsonb,true),
('demo-minseo','민서','역사·한옥·건축의 이야기를 천천히 관람하는 문화 여행을 좋아해요.',ARRAY['역사문화','한옥','건축','관람']::text[],'{"activity": 30, "space": 40, "environment": 20, "content": 10, "pace": 40}'::jsonb,true),
('demo-doyun','도윤','바다와 해안의 레포츠를 중심으로 움직이는 여행을 좋아해요.',ARRAY['바다','레포츠','액티비티','야외']::text[],'{"activity": 100, "space": 100, "environment": 90, "content": 80, "pace": 85}'::jsonb,true),
('demo-seoyeon','서연','도시의 시장·쇼핑 거리와 골목을 둘러보는 여행을 좋아해요.',ARRAY['쇼핑','골목','도시','관람']::text[],'{"activity": 60, "space": 50, "environment": 5, "content": 30, "pace": 60}'::jsonb,true),
('demo-taeo','태오','양조장의 역사와 전통주 문화를 배우는 관람·체험 여행을 좋아해요.',ARRAY['주캉스','양조장','전통주','막걸리','체험']::text[],'{"activity": 50, "space": 25, "environment": 40, "content": 90, "pace": 40}'::jsonb,true),
